#include "../CustomHeadsetOpenVR/src/Tracking/NativePoseBridge.h"
#include <iostream>
#include <functional>
#include <vector>
#include <cmath>
#include <limits>
#include <stdexcept>
using namespace dreamair;
static void Require(bool ok,const char* msg){if(!ok)throw std::runtime_error(msg);}
static bool Near(double a,double b){return std::abs(a-b)<1e-8;}
static vr::DriverPose_t Pose(double x=0){vr::DriverPose_t p{};p.qRotation.w=p.qWorldFromDriverRotation.w=p.qDriverFromHeadRotation.w=1;p.vecPosition[0]=x;p.poseIsValid=p.deviceIsConnected=true;p.result=vr::TrackingResult_Running_OK;return p;}
static bool Align(NativePoseBridge& b,const vr::DriverPose_t& source,const vr::DriverPose_t& native,double now,vr::DriverPose_t& out){bool result=false;for(double t:{now-.15,now-.075,now}){b.Observe(0,source,t);result=b.Prepare(0,native,t,out);}return result;}
int main(){
    std::vector<std::pair<const char*,std::function<void()>>> tests;
    auto add=[&](const char* name,std::function<void()> f){tests.emplace_back(name,f);};
    add("disabled passes lighthouse and emits no native pose",[]{NativePoseBridge b;b.Register(0);auto p=Pose(),out=Pose();Require(b.Observe(0,p,1),"source blocked");Require(!b.Prepare(0,p,1,out),"native emitted when disabled");});
    add("identity alignment and motion",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto p=Pose(3),out=Pose();b.Observe(0,p,1);Require(Align(b,p,Pose(1),1.01,out),"not aligned");Require(Near(out.vecWorldFromDriverTranslation[0],2),"translation wrong");b.Prepare(0,Pose(2),1.02,out);Require(Near(out.vecPosition[0]+out.vecWorldFromDriverTranslation[0],4),"native motion not preserved");});
    add("world and head reference transforms included",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto p=Pose(1),out=Pose();p.qWorldFromDriverRotation={std::sqrt(.5),0,0,std::sqrt(.5)};p.vecWorldFromDriverTranslation[0]=10;p.vecDriverFromHeadTranslation[0]=2;p.qDriverFromHeadRotation={std::sqrt(.5),0,0,std::sqrt(.5)};b.Observe(0,p,1);Require(Align(b,p,Pose(),1.01,out),"not aligned");Require(Near(out.vecWorldFromDriverTranslation[0],10)&&Near(out.vecWorldFromDriverTranslation[1],3),"head/world translation omitted");Require(Near(std::abs(out.qWorldFromDriverRotation.z),1),"head/world orientation omitted");});
    add("invalid lighthouse cannot calibrate",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto p=Pose(),out=Pose();p.poseIsValid=false;b.Observe(0,p,1);Require(!b.Prepare(0,Pose(),1.01,out)&&!b.Snapshot().aligned,"invalid calibrated");});
    add("calibrating source result cannot seed forced validity",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto p=Pose(),out=Pose();p.result=vr::TrackingResult_Calibrating_OutOfRange;b.Observe(0,p,1);Require(!b.Prepare(0,Pose(),1.01,out),"non-OK calibrated");});
    add("stale pairing waits for fresh source",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Require(!b.Prepare(0,Pose(),1.2,out),"old source calibrated");b.Observe(0,Pose(),1.21);Require(Align(b,Pose(),Pose(),1.22,out),"fresh pair refused");});
    add("fresh callbacks with different represented times cannot align",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto source=Pose(),out=Pose();source.poseTimeOffset=-.2;b.Observe(0,source,1);Require(!b.Prepare(0,Pose(),1.01,out),"different instants calibrated");});
    add("alignment requires a steady window",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Require(!b.Prepare(0,Pose(),1,out),"single pair locked alignment");b.Observe(0,Pose(),1.05);Require(!b.Prepare(0,Pose(),1.05,out),"short window locked alignment");b.Observe(0,Pose(),1.10);Require(!b.Prepare(0,Pose(),1.10,out),"short window locked alignment");b.Observe(0,Pose(),1.15);Require(b.Prepare(0,Pose(),1.15,out),"steady window refused");});
    add("moving or inconsistent pairs reset alignment window",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose(),moving=Pose();moving.vecAngularVelocity[1]=2;Require(!Align(b,Pose(),moving,1,out),"turning calibrated");auto jumping=Pose(.3);b.Observe(0,Pose(),1.1);b.Prepare(0,Pose(),1.1,out);b.Observe(0,Pose(),1.175);b.Prepare(0,Pose(),1.175,out);b.Observe(0,jumping,1.25);Require(!b.Prepare(0,Pose(),1.25,out),"jumping alignment accepted");Require(Align(b,Pose(),Pose(),1.5,out),"settled alignment refused");});
    add("rotating alignment candidate resets steady window",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose(),turn=Pose();turn.qRotation={std::cos(.1),0,std::sin(.1),0};b.Observe(0,Pose(),1);b.Prepare(0,Pose(),1,out);b.Observe(0,Pose(),1.075);b.Prepare(0,Pose(),1.075,out);b.Observe(0,turn,1.15);Require(!b.Prepare(0,Pose(),1.15,out),"rotation discrepancy calibrated");});
    add("noncommuting rotations and rotated head offset",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto s=Pose(1),n=Pose(4),out=Pose();double h=std::sqrt(.5);s.vecPosition[1]=2;s.vecPosition[2]=3;s.qWorldFromDriverRotation={h,0,0,h};s.qRotation={h,h,0,0};s.qDriverFromHeadRotation={h,0,h,0};s.vecDriverFromHeadTranslation[0]=2;s.vecDriverFromHeadTranslation[1]=3;s.vecDriverFromHeadTranslation[2]=4;s.vecWorldFromDriverTranslation[0]=10;n.qRotation={h,0,h,0};n.vecPosition[1]=5;n.vecPosition[2]=6;Require(Align(b,s,n,1,out),"not aligned");Require(Near(out.vecWorldFromDriverTranslation[0],6)&&Near(out.vecWorldFromDriverTranslation[1],-1)&&Near(out.vecWorldFromDriverTranslation[2],1),"noncommuting position wrong");Require(Near(out.qWorldFromDriverRotation.w,.5)&&Near(out.qWorldFromDriverRotation.x,.5)&&Near(out.qWorldFromDriverRotation.y,.5)&&Near(out.qWorldFromDriverRotation.z,.5),"noncommuting rotation wrong");});
    add("delayed submission rebases relative offset",[]{auto p=Pose();p.poseTimeOffset=-.005;auto q=RebaseNativePose(p,1,1.04);Require(Near(q.poseTimeOffset,-.045),"submission latency omitted");});
    add("delayed native sample cannot bypass stale rejection",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1.3);auto p=RebaseNativePose(Pose(),1,1.3);Require(!b.Prepare(0,p,1.3,out)&&!b.Snapshot().pimaxValid,"stale result accepted");});
    add("invalid native cannot calibrate",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto p=Pose(),out=Pose();p.poseIsValid=false;b.Observe(0,Pose(),1);Require(!b.Prepare(0,p,1.01,out),"bad native calibrated");});
    add("continues through lighthouse loss",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Require(Align(b,Pose(),Pose(),1.01,out),"not aligned");auto p=Pose(100);p.poseIsValid=false;Require(!b.Observe(0,p,2),"competing source allowed");Require(b.Prepare(0,Pose(.1),2.01,out)&&out.poseIsValid&&Near(out.vecPosition[0],.1),"native froze after source loss");});
    add("native invalid is recorded before force flags",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Align(b,Pose(),Pose(),1.01,out);auto p=Pose();p.poseIsValid=false;Require(b.Prepare(0,p,1.02,out)&&!out.poseIsValid&&!b.Snapshot().pimaxValid&&b.Snapshot().pimaxInvalid==1,"native loss hidden");});
    add("malformed native sanitized",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Align(b,Pose(),Pose(),1.01,out);auto p=Pose();p.vecPosition[0]=std::numeric_limits<double>::quiet_NaN();Require(b.Prepare(0,p,1.02,out)&&!out.poseIsValid&&std::isfinite(out.vecPosition[0]),"NaN escaped");});
    add("native pose offset bounds",[]{for(double offset:{-.3,.1}){NativePoseBridge b;b.Register(0);b.Configure(true);auto p=Pose(),out=Pose();p.poseTimeOffset=offset;b.Observe(0,Pose(),1);Require(!b.Prepare(0,p,1.01,out),"old/future pose calibrated");}});
    add("source change clears alignment",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Align(b,Pose(),Pose(),1.01,out);b.Configure(false);Require(!b.Snapshot().aligned&&b.Observe(0,Pose(),2),"old alignment retained");b.Configure(true);Require(!b.Prepare(0,Pose(),3,out),"old pair reused");});
    add("device deactivate clears state",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Align(b,Pose(),Pose(),1.01,out);b.Unregister(0);Require(!b.Snapshot().aligned&&!b.Prepare(0,Pose(),1.02,out),"inactive native emitted");});
    add("non-target devices pass through",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto out=Pose();b.Observe(0,Pose(),1);Align(b,Pose(),Pose(),1.01,out);Require(b.Observe(1,Pose(),1.02)&&!b.Prepare(1,Pose(),1.02,out),"controller intercepted");});
    add("malformed source never calibrates",[]{NativePoseBridge b;b.Register(0);b.Configure(true);auto p=Pose(),out=Pose();p.qRotation={};b.Observe(0,p,1);Require(!b.Prepare(0,Pose(),1.01,out),"bad source quaternion calibrated");});
    int passed=0;for(auto& t:tests){try{t.second();passed++;std::cout<<"PASS "<<t.first<<'\n';}catch(const std::exception& e){std::cout<<"FAIL "<<t.first<<": "<<e.what()<<'\n';}}
    std::cout<<passed<<'/'<<tests.size()<<" passed\n";return passed==tests.size()?0:1;
}
